-- Table: standard_divisions
CREATE TABLE IF NOT EXISTS public."standard_divisions" (
  "id" bigint NOT NULL DEFAULT nextval('standard_divisions_id_seq'::regclass),
  "school_standard_id" bigint NOT NULL,
  "division" character varying NOT NULL,
  "created_at" timestamp without time zone NOT NULL DEFAULT now()
);


-- Table: students
CREATE TABLE IF NOT EXISTS public."students" (
  "id" bigint NOT NULL DEFAULT nextval('students_id_seq'::regclass),
