  "parent_phone" character varying,
  "active" boolean DEFAULT true,
  "status" character varying,
  "created_at" timestamp without time zone,
  "updated_at" timestamp without time zone,
  "avatar" text,
  "age_group" character varying,
  "auth_provider" character varying,
  "daily_goal_minutes" integer,
  "email_verification_token" character varying,
  "english_level" character varying,
  "expo_push_token" character varying,
  "interests" character varying,
  "learning_goal" character varying,
  "native_language" character varying,
  "preferred_accent" character varying,
  "preferred_voice" character varying,
  "reset_otp" character varying,
  "reset_otp_expiry" timestamp without time zone,
