  "reset_password_token_expiry" timestamp without time zone,
  "welcome_completed" boolean DEFAULT false,
  "onboarding_completed" boolean DEFAULT false,
  "email_verified" boolean DEFAULT false,
  "user_type" character varying DEFAULT 'STANDARD'::character varying,
  "role" character varying DEFAULT 'STUDENT'::character varying,
