INSERT INTO public."chat_messages" ("id", "better_sentence", "created_at", "explanation", "follow_up_question", "grammar_correction", "message", "sender", "vocabulary_suggestions", "voice_enabled", "session_id") VALUES ('242', '“Could you translate this sentence for me?”', '2026-09-29T01:52:36.914Z', 'Adding “about” after “talk” shows the topic you are discussing.', 'Would you like to learn how to say more polite requests in Hindi?', '“just talk this sentence” → “just talk about this sentence.” The word “about” is needed after “talk.”', 'The Hindi sentence “aap yaha aa jayiye” means “please come here.” It is a polite way to ask someone to come to a place.', 'ai', '**translate** – change words from one language to another; **phrase** – a short group of words that form a meaning.', true, '140') ON CONFLICT DO NOTHING;
INSERT INTO public."chat_messages" ("id", "better_sentence", "created_at", "explanation", "follow_up_question", "grammar_correction", "message", "sender", "vocabulary_suggestions", "voice_enabled", "session_id") VALUES ('243', NULL, '2026-09-29T01:52:58.540Z', NULL, NULL, NULL, 'say it', 'user', NULL, true, '140') ON CONFLICT DO NOTHING;
INSERT INTO public."chat_messages" ("id", "better_sentence", "created_at", "explanation", "follow_up_question", "grammar_correction", "message", "sender", "vocabulary_suggestions", "voice_enabled", "session_id") VALUES ('244', '“Please come here.” (or “Come on over.”)', '2026-09-29T01:53:00.108Z', 'Adding “please” makes the request sound polite and friendly.', 'Would you like to learn how to say “thank you” in English?', '✅ Your sentence is correct.', 'The English way to say “aap yaha aa jayiye” is “Please come here.” You can also say “Come on over.”', 'ai', 'please – a polite word used when asking; over – used to mean “to this place.”', true, '140') ON CONFLICT DO NOTHING;
INSERT INTO public."chat_messages" ("id", "better_sentence", "created_at", "explanation", "follow_up_question", "grammar_correction", "message", "sender", "vocabulary_suggestions", "voice_enabled", "session_id") VALUES ('245', NULL, '2026-09-29T01:53:24.228Z', NULL, NULL, NULL, 'what are you doing', 'user', NULL, true, '140') ON CONFLICT DO NOTHING;
INSERT INTO public."chat_messages" ("id", "better_sentence", "created_at", "explanation", "follow_up_question", "grammar_correction", "message", "sender", "vocabulary_suggestions", "voice_enabled", "session_id") VALUES ('246', NULL, '2026-09-29T01:53:25.780Z', 'This question uses the present continuous tense to ask about an activity happening now.', 'What are you doing right now?', '✅ Your sentence is correct.', 'I’m just chatting with you and helping you practice English.', 'ai', 'currently – at this moment; chatting – talking informally', true, '140') ON CONFLICT DO NOTHING;
