INSERT INTO public."chat_messages" ("id", "better_sentence", "created_at", "explanation", "follow_up_question", "grammar_correction", "message", "sender", "vocabulary_suggestions", "voice_enabled", "session_id") VALUES ('251', '“After a long day, I relax by reading a book.”', '2026-09-30T00:03:48.100Z', '“Unwind” is a friendly word for taking a break and feeling calm.', 'How do you usually unwind after work or a busy day?', '✅ Your sentence is correct.', 'Sure! You could say: “After a long day, I like to unwind by reading a book.”', 'ai', 'unwind – to relax after stress; relax – to become less tense.', true, '145') ON CONFLICT DO NOTHING;
INSERT INTO public."chat_messages" ("id", "better_sentence", "created_at", "explanation", "follow_up_question", "grammar_correction", "message", "sender", "vocabulary_suggestions", "voice_enabled", "session_id") VALUES ('252', NULL, '2026-09-30T00:04:02.908Z', NULL, NULL, NULL, 'Thanks! Any other common phrases for relaxing?', 'user', NULL, true, '145') ON CONFLICT DO NOTHING;
INSERT INTO public."chat_messages" ("id", "better_sentence", "created_at", "explanation", "follow_up_question", "grammar_correction", "message", "sender", "vocabulary_suggestions", "voice_enabled", "session_id") VALUES ('253', NULL, '2026-09-30T00:04:04.120Z', 'Both phrases sound casual and are common in everyday chat.', 'What’s your favorite activity to kick back with when you have free time?', '✅ Your sentence is correct.', 'You’re welcome! Some easy ways to talk about relaxing are: “I love to kick back with a good movie,” or “I enjoy chilling out with music.”', 'ai', 'kick back – to relax and take it easy; chill out – to relax, often informally.', true, '145') ON CONFLICT DO NOTHING;
