INSERT INTO public."conversation_feedbacks" ("id", "better_sentences", "grammar_corrections", "summary", "vocabulary_suggestions", "session_id") VALUES ('118', 'Instead of "Hi! I''m happy to practice English with you today.", you could say "Hi! I''m excited to practice English with you today." And replace "Could you tell me more about that?" with "Could you tell me more about it?" or "Could you elaborate on that?" for smoother flow.', 'Minor stylistic tweak: "That is very interesting!" can be more natural as "That''s very interesting!" otherwise no grammatical errors were observed.', 'The student used polite, grammatically correct sentences but the contribution was brief, showing limited lexical variety and fluency.', '"I''m excited to practice English with you today", "That''s fascinating!", "Could you elaborate on that?", "I’d love to hear more about it"', '638') ON CONFLICT DO NOTHING;
