INSERT INTO public."vocabulary" ("id", "antonym", "created_at", "example_sentence", "favorite", "meaning", "synonym", "word", "user_id", "student_id", "collocations", "level", "mastered", "part_of_speech", "phonetic") VALUES ('48', 'careless, indifferent, sloppy, negligent, uncritical', '2026-09-16T11:28:13.101Z', 'She is so fastidious about her appearance that she spends an hour each morning selecting the perfect outfit.', false, 'Showing great attention to detail; very careful and demanding about accuracy, cleanliness, or precision.', 'meticulous, exacting, particular, scrupulous, choosy, fussy', 'Fastidious', '94', NULL, 'fastidious eater, fastidious about cleanliness, fastidious standards, fastidious attention, fastidious habit', 'Advanced', false, 'adjective', '/fæˈstɪdiəs/') ON CONFLICT DO NOTHING;
INSERT INTO public."vocabulary" ("id", "antonym", "created_at", "example_sentence", "favorite", "meaning", "synonym", "word", "user_id", "student_id", "collocations", "level", "mastered", "part_of_speech", "phonetic") VALUES ('49', 'yielding, weak, indecisive, feeble, lax, irresolute', '2026-09-17T05:07:37.680Z', 'She showed a tenacious determination to finish the marathon despite the rain.', true, 'Holding fast; persistent and determined; not easily giving up or letting go.', 'persistent, determined, steadfast, dogged, resolute, unyielding, stubborn', 'Tenacious', '94', NULL, 'tenacious grip, tenacious attitude, tenacious pursuit, tenacious athlete, tenacious spirit', 'Intermediate', false, 'adjective', '/təˈneɪʃəs/') ON CONFLICT DO NOTHING;
INSERT INTO public."vocabulary" ("id", "antonym", "created_at", "example_sentence", "favorite", "meaning", "synonym", "word", "user_id", "student_id", "collocations", "level", "mastered", "part_of_speech", "phonetic") VALUES ('65', 'exhaling, calming, relaxing, contentment', '2026-10-01T23:47:39.818Z', 'After being told he couldn''t go out, he left the room in a huff, huffing loudly as he slammed the door.', false, 'The act of breathing in a vaporized substance, especially an inhalant; also, a display of irritation or annoyance, often expressed by breathing heavily or speaking in a sulky manner.', 'inhaling, breathing, puffing, snorting, fuming, sulking', 'huffing', '94', NULL, 'huffing and puffing, huffing inhalants, huffing a cigarette, in a huff, huffing with anger', 'Intermediate', false, 'verb (present participle) / noun (gerund)', '/ˈhʌfɪŋ/') ON CONFLICT DO NOTHING;
INSERT INTO public."vocabulary" ("id", "antonym", "created_at", "example_sentence", "favorite", "meaning", "synonym", "word", "user_id", "student_id", "collocations", "level", "mastered", "part_of_speech", "phonetic") VALUES ('66', 'streaming, direct playback, real‑time processing, uninterrupted flow', '2026-10-02T00:07:28.622Z', 'The video kept freezing because of buffering on the slow Wi‑Fi connection.', false, 'The process of temporarily storing data in a buffer to compensate for differences in data transmission rates, often causing a pause or delay in playback or processing.', 'caching, preloading, queuing, temporizing, holding', 'buffering', '94', NULL, 'buffering delay, buffering time, buffering issue, buffering problem, reduce buffering, excessive buffering', 'Intermediate', false, 'verb (present participle) / noun (gerund)', '/ˈbʌf.ər.ɪŋ/') ON CONFLICT DO NOTHING;
INSERT INTO public."vocabulary" ("id", "antonym", "created_at", "example_sentence", "favorite", "meaning", "synonym", "word", "user_id", "student_id", "collocations", "level", "mastered", "part_of_speech", "phonetic") VALUES ('67', 'stopped, parked, halted, dispersed, scattered', '2026-10-02T00:07:42.093Z', 'She drove the truck through the snowstorm, and later the farmer gathered the cattle into a large drove.', false, 'The past tense of the verb ''drive'', meaning to have operated a vehicle or guided something; also a noun meaning a large group or herd of animals.', 'operated, piloted, steered, guided, herd, flock, pack', 'drove', '94', NULL, 'drove a car, drove home, drove the truck, drove the herd, cattle drove, drove away', 'Intermediate', false, 'verb (past tense) / noun', '/droʊv/') ON CONFLICT DO NOTHING;
